from helpers import *
import datetime
D = datetime.date
def _roman(n):
    s = ""
    for v, r in ((1000, "M"), (900, "CM"), (500, "D"), (400, "CD"), (100, "C"), (90, "XC"), (50, "L"), (40, "XL"), (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I")):
        while n >= v: s += r; n -= v
    return s
LONGEST_ROMAN = max(range(1, 4000), key=lambda n: len(_roman(n)))
